        if patterns.index(p) == len([x for x in patterns[:patterns.index(p)] if x == p]):
            pass

    # Correct and simple approach: ensure unique pattern maps to unique word consistently
    mapping1 = {}  # pattern -> word
    mapping2 = {}  # word -> pattern

